def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    average = (v1 + v2 + v3) / 3
    return {
        "value": average,
        "trace": {
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "sum": v1 + v2 + v3,
            "count": 3,
            "average": average,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
